INSERT INTO properties (id, slug, name, area, city, img, price, old_price, rating, reviews_count, beds, baths, guests, ptype, badge, badge_gold, instant, policy, map_x, map_y, featured, is_new, tour, floor_label, sold_out, description, ai_summary, host_id, status, sort_order) VALUES
  (1, 'onyx', 'The Onyx Penthouse', 'Lekki Phase 1', 'Lagos', 'p1', 185000, 210000, 4.97, 128, 3, 3.5, 6, 'Penthouse', 'Jollof Verified', 1, 1, 'moderate', 0.29, 0.72, 1, 0, 1, '3 Bed Penthouse', NULL, 'A dark, cinematic penthouse in the sky above Lekki Phase 1. Black marble walls, brass detailing and a private cinema — engineered for quiet drama, with the Lagos skyline flickering beyond 12-foot glass.', 'Guests love the cinema room, the flawless Wi-Fi for video calls, and the concierge''s speed. A few noted the lift can be slow at peak hours.', 1, 'live', 0),
  (2, 'ocean-spearl', 'Ocean Pearl Suite', 'Victoria Island', 'Lagos', 'p2', 145000, NULL, 4.92, 96, 2, 2, 4, 'Oceanfront Suite', 'Superhost', 0, 1, 'flexible', 0.52, 0.42, 1, 0, 1, '2 Bed Suite', NULL, 'Wake to the Atlantic. A serene two-bedroom suite with a private balcony over the water, soft linen, warm oak and a slow morning light that turns the ocean to silver.', 'Guests consistently praise the sunrise view and digital check-in. The building''s gym gets a few mentions as small.', 1, 'live', 1),
  (3, 'villa-azur', 'Villa Azur', 'Banana Island', 'Lagos', 'p3', 420000, NULL, 4.99, 74, 4, 5, 8, 'Private Villa', 'Jollof Verified', 1, 0, 'strict', 0.36, 0.56, 1, 0, 1, '4 Bed Villa', '2026-12-20/2027-01-05', 'Banana Island''s quietest address. A private infinity pool melting into the lagoon, palm-framed terraces, and a villa team on call. This is Nigerian luxury at its most unhurried.', 'Perfect scores across the board. Guests highlight the boat jetty and the invisible-but-present villa team. High demand — book early or join the waitlist.', 1, 'live', 2),
  (4, 'sky-garden', 'The Sky Garden Terrace', 'Ikoyi', 'Lagos', 'p4', 210000, NULL, 4.95, 143, 3, 3, 6, 'Terrace Residence', 'Superhost', 0, 1, 'moderate', 0.47, 0.68, 1, 0, 1, '3 Bed Terrace', NULL, 'A lantern-lit rooftop over Ikoyi. Outdoor lounge, heat lamps, and the whole lagoon as your backdrop — designed for golden-hour dinners and long, warm nights.', 'The terrace is the star — guests mention sunsets constantly. Nightlife watchers note street noise on weekends; earplugs provided.', 1, 'live', 3),
  (5, 'maitama', 'Maitama Executive Residence', 'Maitama', 'Abuja', 'p5', 165000, NULL, 4.9, 88, 2, 2.5, 4, 'Executive Suite', 'Corporate Ready', 0, 1, 'flexible', 0.75, 0.2, 0, 0, 1, '2 Bed Executive', NULL, 'The address of choice for dignitaries and executives. A calm, brass-lit residence above the green hills of Maitama, minutes from the Central Business District.', 'Corporate guests rate value highly thanks to PO billing and invoicing. The desk and meeting corner get frequent praise; gym access requires a short walk.', 1, 'live', 4),
  (6, 'atelier-loft', 'The Atelier Loft', 'Eko Atlantic', 'Lagos', 'p6', 135000, 155000, 4.87, 66, 2, 2, 4, 'Designer Loft', 'Last-Minute Deal', 1, 1, 'flexible', 0.22, 0.68, 0, 1, 0, '2 Bed Loft', NULL, 'A double-height loft in the city of the future. Raw concrete softened with oak and brass, and Eko Atlantic''s skyline glowing past floor-to-ceiling glass.', 'Guests call it ''architectural eye candy''. A few note morning construction noise in the district — the double glazing handles most of it.', 1, 'live', 5),
  (7, 'heritage-house', 'Heritage House Lagos', 'Old Ikoyi', 'Lagos', 'p7', 120000, NULL, 4.93, 112, 3, 2, 6, 'Heritage Stay', 'Cultural Heritage', 0, 0, 'moderate', 0.5, 0.62, 0, 0, 1, '3 Bed Courtyard House', NULL, 'A lovingly restored 1950s Ikoyi courtyard house — shutters, terrazzo and antique woods, layered with contemporary comfort and Nigerian art on every wall.', 'Guests describe it as a museum that is also home. The courtyard breakfasts, curated art and the house tour are mentioned in most reviews.', 1, 'live', 6),
  (8, 'lagoon-villa', 'The Lagoon Villa', 'Victoria Island', 'Lagos', 'hero', 175000, NULL, 4.96, 151, 3, 3.5, 6, 'Waterfront Villa', 'Waterfront Escapes', 0, 1, 'moderate', 0.44, 0.5, 1, 0, 1, '3 Bed Villa', NULL, 'Glass-walled living above the lagoon. An emerald-and-gold great room that turns into a lantern at dusk, with the city shimmering across the water.', 'The dock at sunset is the most-photographed spot in the portfolio. Generous for families; split payments made two-month stays popular with relocators.', 1, 'live', 7),
  (9, 'lagoon-duplex', 'Lekki Lagoon Duplex', 'Lekki Phase 1', 'Lagos', 'p10', 165000, NULL, 4.88, 59, 4, 4.5, 8, 'Furnished Townhouse', 'Family Favourite', 0, 1, 'moderate', 0.31, 0.78, 0, 1, 1, '4 Bed Duplex', NULL, 'A warm, wood-screened duplex with a plunge-pool courtyard — made for families and long-term comfort. Quiet street, generous living, thoughtful storage.', 'Families love the playroom and pantry. Excellent value for 30+ nights — monthly pricing with -25% plus housekeeping keeps long stays effortless.', 1, 'live', 8),
  (10, 'eko-icon', 'The Eko Icon Suite', 'Eko Atlantic', 'Lagos', 'p11', 95000, NULL, 4.85, 41, 1, 1.5, 2, 'Hotel Suite', 'New This Season', 0, 1, 'flexible', 0.25, 0.62, 0, 1, 0, '1 Bed Suite', NULL, 'A boutique one-bedroom suite with soft champagne tones and city views — the smart, elegant base for a weekend in Eko Atlantic. Hotel services, apartment privacy.', 'Effortless for short stays — guests praise the 24/7 reception and rain shower. It books fast on event weekends.', 1, 'live', 9),
  (11, 'abuja-sky', 'Abuja Sky Residence', 'Maitama', 'Abuja', 'p9', 190000, NULL, 4.91, 77, 3, 3, 5, 'Penthouse', 'Corporate Ready', 0, 0, 'strict', 0.79, 0.26, 0, 0, 1, '3 Bed Penthouse', NULL, 'High above the green hills of Abuja — a charcoal-and-brass penthouse with sunset terraces on two sides and the skyline of the capital at your feet.', 'Terraces and privacy are the recurring love letters. A couple of guests asked for earlier check-in — late checkout is available on request.', 1, 'live', 10),
  (12, 'island-retreat', 'The Island Retreat', 'Banana Island', 'Lagos', 'p12', 240000, NULL, 4.94, 63, 3, 3, 6, 'Garden Villa', 'Jollof Verified', 1, 0, 'moderate', 0.34, 0.5, 0, 0, 1, '3 Bed Garden Villa', NULL, 'A garden villa wrapped in palms on the most exclusive island in West Africa — daybeds by a still reflecting pool, birdsong mornings and complete, guarded calm.', 'The garden is the soul of the house — guests describe it as ''a private botanical resort''. Chef bookings sell out, so reserve ahead.', 1, 'live', 11);
