INSERT INTO reviews (property_id, author, meta, body, rating, status) VALUES
  (1, 'Adaeze O.', 'Lagos · Apr 2026', 'The cinema room alone is worth it. Spotless, concierge arranged a private chef — impeccable.', 5, 'published'),
  (1, 'James K.', 'London · Jun 2026', 'Feels like a five-star hotel floor, but entirely yours. Escrow payment gave total peace of mind.', 5, 'published'),
  (1, 'Chuka E.', 'Abuja · Aug 2026', 'Smart-home everything, blackout blinds, flawless Wi-Fi for calls. Best stay I''ve had in Lagos.', 5, 'published'),
  (2, 'Funmi A.', 'Lagos · Mar 2026', 'The balcony view at sunrise is unbeatable. Concierge had a boat booked in ten minutes.', 5, 'published'),
  (2, 'Daniel M.', 'Accra · Jun 2026', 'Spotless, quiet, and the digital check-in meant midnight arrival was effortless.', 5, 'published'),
  (2, 'Sarah B.', 'New York · Aug 2026', 'Long-stay discount + split payment made a month here very comfortable.', 5, 'published'),
  (3, 'Bolanle T.', 'Lagos · Feb 2026', 'We hosted a small engagement here. The team was invisible until we needed them — flawless.', 5, 'published'),
  (3, 'Hans W.', 'Berlin · May 2026', 'The best villa we''ve stayed at anywhere in Africa. The boat jetty is a touch of genius.', 5, 'published'),
  (3, 'Zainab M.', 'Dubai · Jul 2026', 'Escrow release only after check-in confirmation — exactly how luxury platforms should work.', 5, 'published'),
  (4, 'Tobi F.', 'Lagos · Jan 2026', 'Sunsets from this terrace should be illegal. One of Lagos'' best-kept secrets.', 5, 'published'),
  (4, 'Anna P.', 'Paris · Apr 2026', 'Beautiful, airy, and the welcome package with chin-chin and wine was so thoughtful.', 5, 'published'),
  (4, 'Emeka N.', 'Enugu · Aug 2026', 'Booked via the AI concierge — three messages and it was done.', 5, 'published'),
  (5, 'Ngozi U.', 'Abuja · May 2026', 'Corporate billing with PO numbers was seamless for our team''s month-long project.', 5, 'published'),
  (5, 'Robert S.', 'Nairobi · Jul 2026', 'The quietest executive stay in Abuja. Wi-Fi never blinked during two weeks of calls.', 5, 'published'),
  (5, 'Hadiza Y.', 'Kano · Aug 2026', 'Airport pickup, check-in, everything arranged by message. Effortless.', 5, 'published'),
  (6, 'Kelechi O.', 'Lagos · Aug 2026', 'Architectural eye candy, and 15% off for booking within 48 hours of check-in.', 5, 'published'),
  (6, 'Grace L.', 'Accra · Aug 2026', 'The loft has a gallery feel. Concierge recommended an amazing rooftop dinner nearby.', 5, 'published'),
  (6, 'Uche A.', 'Lagos · Sep 2026', 'Checking in took ninety seconds with the keyless code.', 5, 'published'),
  (7, 'Yewande S.', 'Lagos · Mar 2026', 'Stayed two nights and felt like I''d been to a museum that also happens to be home.', 5, 'published'),
  (7, 'Olivia R.', 'Cape Town · Jun 2026', 'The courtyard breakfasts were the highlight of my Nigeria trip.', 5, 'published'),
  (7, 'Ibrahim G.', 'Kano · Aug 2026', 'Beautiful, storied, immaculate. The house tour was a lovely touch.', 5, 'published'),
  (8, 'Amina Z.', 'Abuja · Feb 2026', 'We watched the sunset from the dock every evening. Pure magic.', 5, 'published'),
  (8, 'Tom H.', 'London · May 2026', 'The AI review summary said guests love the view — it undersold it.', 5, 'published'),
  (8, 'Chioma P.', 'Lagos · Jul 2026', 'Split payments made a two-month stay painless. Felt like a resident.', 5, 'published'),
  (9, 'Damilola A.', 'Lagos · Aug 2026', 'We moved in for six weeks between homes. It absorbed our whole family life beautifully.', 5, 'published'),
  (9, 'Kate O.', 'Ibadan · Sep 2026', 'The courtyard pool saved our summer. Kids never wanted to leave.', 5, 'published'),
  (9, 'Femi S.', 'Abuja · Sep 2026', 'Secure parking, backup power, calm street. Long-stay done right.', 5, 'published'),
  (10, 'Bella E.', 'Lagos · Sep 2026', 'Perfect weekend base. The reception team is lovely and the bed is cloud-soft.', 5, 'published'),
  (10, 'Ahmed B.', 'Kano · Sep 2026', 'Check-in took two minutes. Great Wi-Fi, great shower, great value.', 5, 'published'),
  (10, 'Rita N.', 'Port Harcourt · Sep 2026', 'Eko Atlantic''s best budget-luxury secret.', 5, 'published'),
  (11, 'Moses A.', 'Abuja · Jun 2026', 'Sunset on the west terrace, briefing in the meeting corner. This is the executive life.', 5, 'published'),
  (11, 'Claire D.', 'London · Jul 2026', 'The most beautiful home I''ve stayed in in West Africa. Immaculate.', 5, 'published'),
  (11, 'Yakubu M.', 'Kaduna · Sep 2026', 'Quiet, secure, elegant. The booking request was confirmed within an hour.', 5, 'published'),
  (12, 'Oluwaseun F.', 'Lagos · Apr 2026', 'Birdsong mornings, pool reflections, total privacy. A quiet kind of luxury.', 5, 'published'),
  (12, 'Marie L.', 'Paris · Jul 2026', 'The rainshower under the palms is unforgettable. Villa team was superb.', 5, 'published'),
  (12, 'Tunde K.', 'Lagos · Sep 2026', 'Booked the chef for a birthday lunch. Effortless, memorable, immaculate.', 5, 'published');
