INSERT INTO experiences (id, slug, name, category, img, price, duration, description, active, sort_order) VALUES
  (1, 'cruise', 'Lagos Lagoon Cruise', 'Signature', 'exp-boat', 85000, '3 hours', 'Sunset aboard a private yacht — champagne, canapés and the skyline drifting past on the world''s most storied lagoon.', 1, 0),
  (2, 'chef', 'Private Chef & Jollof Masterclass', 'Taste', 'exp-chef', 55000, '2–3 hours', 'A Jollof Living-approved chef cooks a tasting menu in your kitchen — or teaches you the legend of the perfect jollof.', 1, 1),
  (3, 'spa', 'Spa & Wellness Ritual', 'Restore', 'exp-spa', 45000, '90 min', 'In-residence massages, facials and private trainers, delivered to your door by vetted therapists.', 1, 2),
  (4, 'tour', 'Art & Heritage City Tour', 'Culture', 'exp-tour', 35000, '4 hours', 'Nike Art Gallery, Freedom Park and the creative studios of Lagos, guided by artists and local historians.', 1, 3),
  (5, 'transfer', 'Airport Transfer', 'Essential', 'p11', 25000, '45 min', 'Vetted chauffeurs in luxury SUVs — meet-and-greet, flight tracking and a chilled bottle on board.', 1, 4),
  (6, 'events', 'Event Curation', 'Bespoke', 'p4', 120000, 'Half day', 'Birthdays, proposals, corporate retreats — our events team designs and runs the whole thing.', 1, 5),
  (7, 'shopper', 'Personal Shopper', 'Bespoke', 'p7', 30000, '3 hours', 'Pre-stock groceries, fashion-styling runs, or gift sourcing — someone brilliant, on your side.', 1, 6),
  (8, 'festival', 'Festival Calendar', 'Culture', 'exp-tour', 0, 'Ongoing', 'Detty December, Eko Jazz, art weeks — we curate tickets and tables for the moments everyone remembers.', 1, 7);
INSERT INTO blog_posts (id, slug, category, title, date_label, read_time, img, excerpt, body, published, sort_order) VALUES
  (1, 'top-10-stays-lagos', 'Guides', 'The Top 10 Stays in Lagos Right Now', 'Aug 2026', '9 min', 'p1', 'From sky-high penthouses to lagoon villas — the residences defining luxury travel in Lagos this season.', '["Lagos has never had more beautiful places to stay. A decade of architectural ambition, a new wave of design talent and the world''s most vibrant energy have combined into a stay-city without equal.","Our editors visited, slept and hosted at every residence in the current collection, scoring comfort, design, service and location. Here is what rose to the top.","Number one this season is The Onyx Penthouse, a black-marble and brass tour de force in Lekki Phase 1. The private cinema room convinced our judges within the first hour.","Rounding out the list: The Sky Garden Terrace''s sunset lounge, Heritage House''s restored courtyard, and the Eko Icon Suite — the smartest budget-luxury play in the city."]', 1, 0),
  (2, 'jollof-100', 'Food', 'The Legend of Jollof, Explained Over One Plate', 'Jul 2026', '6 min', 'exp-chef', 'Every Nigerian claims the perfect recipe. Our private chefs settle the argument — with party rice, of course.', '["There is no dish in West Africa with a bigger reputation. Jollof rice is the dish of celebration, competition and occasionally international diplomacy.","It begins with a smoky base: onions, peppers, scotch bonnet and tomato, cooked low until the flavour lays down. The rice cooks in that sauce, never after it.","Party rice takes it further — the smoky, slightly charred version cooked over a bigger flame, served at every occasion that matters.","Our private chefs run jollof masterclasses in every residence on request, with the recipe that won them their family bragging rights."]', 1, 1),
  (3, 'guidetodettydecember', 'Culture', 'The Insider''s Guide to Detty December', 'Jun 2026', '11 min', 'p4', 'The world''s greatest month of music, parties and homecoming — and how to live it like a local.', '["When the diaspora flies home, Lagos becomes the happiest city on earth. Detty December is a full month of concerts, festivals, beach days and long dinners.","Base yourself near the action — Vi, Ikoyi or Lekki Phase 1 — and let the concierge build your calendar, because events sell out in days.","Book early. Our best residences are reserved 60 to 90 days ahead, and the villa team at Villa Azur becomes the most popular address in the city.","Use the last-minute deals channel for flexibility, and always arrange transfers in advance — the December roads demand it."]', 1, 2),
  (4, 'work-from-lagos', 'Work', 'Working From Lagos: The Executive Playbook', 'May 2026', '8 min', 'p5', 'Fibre Wi-Fi, power resilience and a desk with a view — how to run a serious work week from Nigeria''s capital.', '["Lagos and Abuja are quietly becoming remote-work capitals. English-speaking, arts-rich, food-obsessed, and connected by subsea cables to Europe in under 60ms.","The key is choosing a residence built for work: dedicated desks, backup generation, and fibre that never blinks. Our Maitama and Eko Atlantic addresses are favourites.","Extend the workday into the evening the Lagos way — rooftop dinner, jazz, then breakfast with lagoon light.","Our Corporate Ready homes support PO billing, traveler policies and monthly invoicing for companies sending teams."]', 1, 3),
  (5, 'longstay-guide', 'Living', 'Six Weeks in Lagoon Living: A Long-Stay Diary', 'Apr 2026', '7 min', 'p12', 'What it actually costs, what it actually feels like, and why monthly-staying is the best way to know a city.', '["We asked a guest who stayed six weeks at The Lagoon Villa to keep a diary: costs, routines, discoveries, and the moments she''d never have found as a tourist.","Week one: the split-payment plan meant the move was painless. Weekly housekeeping kept the villa perfect. Week three: she had a standing table at two restaurants and a regular boatman.","Long-stay pricing drops 25% on monthly bookings, with a digital lease agreement that covers everything in plain language.","By week six she knew the market, the barber, the sunset spot and the tide chart."]', 1, 4),
  (6, 'escrow-explained', 'Trust', 'How Escrow Makes Luxury Stays Safe', 'Mar 2026', '5 min', 'p2', 'Your money is held by Jollof Living until you check in. Here''s the full flow — and why it changes everything.', '["The biggest fear in travel is paying for something that isn''t what you were promised. Escrow removes that anxiety completely.","When you book, your payment is captured but held by Jollof Living — the host has not received it. You check in, inspect, and confirm. Only then are funds released.","If the residence isn''t as described, our Dispute Resolution Centre steps in within hours, not days.","Every booking on the platform is protected this way, with a refund timeline published before you pay."]', 1, 5);
INSERT INTO testimonials (author, meta, quote, active, sort_order) VALUES
  ('Adaeze O.', 'The Onyx Penthouse · Lekki', 'From the airport pickup to the private chef, everything felt considered. This is how luxury travel should work — with African soul.', 1, 0),
  ('James K.', 'Villa Azur · Banana Island', 'I''ve used the big platforms in thirty countries. Nothing matches this finish, this service, or this trust in payments.', 1, 1),
  ('Ngozi U.', 'Maitama Executive · Abuja', 'Our company books a month of suites here. Corporate invoicing, split payments, zero friction.', 1, 2),
  ('Tobi F.', 'The Sky Garden Terrace · Ikoyi', 'The AI concierge planned our whole weekend — boat, chef, late check-out. Three messages, done.', 1, 3),
  ('Hans W.', 'Ocean Pearl · Victoria Island', 'The escrow system means you pay with confidence. Check-in confirmation released the host''s funds — it just works.', 1, 4),
  ('Yewande S.', 'Heritage House · Old Ikoyi', 'An old Lagos house, restored perfectly. I felt the culture in a way no hotel could ever give me.', 1, 5),
  ('Kelechi O.', 'The Atelier Loft · Eko Atlantic', 'Booked the last-minute deal two days before arriving. Best decision of the trip.', 1, 6);
INSERT INTO faqs (question, answer, category, sort_order) VALUES
  ('What are the cancellation policies?', 'Three transparent tiers: Flexible (full refund up to 48h before check-in), Moderate (full refund up to 5 days, 50% after), and Strict (50% up to 14 days). Each listing shows its policy clearly before you book.', NULL, 0),
  ('How do escrow payments work?', 'Your payment is held securely by Jollof Living and released to the host only after you confirm check-in. If the property isn''t as described, our Dispute Resolution Centre and 24/7 team step in.', NULL, 1),
  ('Can I split payments on long stays?', 'Yes. For stays of 30 nights or more you can pay in two installments — 50% at booking and 50% at check-in — easing the financial burden of long-term luxury living.', NULL, 2),
  ('What does Jollof Verified mean?', 'Properties that pass an in-person or video inspection earn the Jollof Verified badge. Every host also completes full KYC identity verification, and every listing is screened by our AI moderation systems.', NULL, 3),
  ('Do I need an extended-stay agreement?', 'For 30+ night stays we generate a digital lease-style agreement with clear terms — signed securely in-app, with a copy stored in your encrypted documents vault.', NULL, 4),
  ('What payment methods do you accept?', 'Cards (Visa, Mastercard, Verve), bank transfer, USSD, mobile money, Paystack, Flutterwave, Stripe, Apple Pay and Google Pay — in NGN, USD, GBP or EUR with real-time exchange rates.', NULL, 5),
  ('How is my identity verified?', 'Three steps: government ID upload, a selfie match, and phone/SMS verification. Verified guests unlock instant booking on more residences and build trust with hosts.', NULL, 6),
  ('Can I host an event at a residence?', 'Selected listings (marked ''Event Hosting'') accept intimate events — birthdays, proposals, small retreats. Always request approval at booking; strict noise policies apply after 10pm.', NULL, 7),
  ('What is Jollof Points and how do I earn them?', 'Earn points per night based on your membership tier (5×–15×). Redeem for discounts, late check-outs, upgrades and experiences. Your ledger is in your account.', NULL, 8),
  ('How do I become a host?', 'Start the listing wizard — you''ll be guided step by step through details, pricing, policies and photos. Our team then verifies and (on request) photographs your property. You can earn from your first booking.', NULL, 9),
  ('Is there help if something goes wrong?', '24/7 support on chat, phone and WhatsApp, an in-app dispute resolution centre, and one-tap emergency assistance. Median first response is under 3 minutes.', NULL, 10),
  ('Do you support corporate travel?', 'Jollof Living for Business provides centralized billing, PO numbers, travel policy enforcement, monthly invoicing and a dedicated account manager. Bookings count toward your company''s travel dashboard.', NULL, 11);
